      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT = path.resolve(__dirname, '..');
const CATALOG_PATH = path.join(ROOT, '.truth_reader', 'catalog.json');
const SELECTOR_PATH = path.join(ROOT, '.truth_reader', 'selector.json');
const EVIDENCE_PATH = path.join(ROOT, '.truth_reader', 'evidence.json');
const PROVENANCE_PATH = path.join(ROOT, '.truth_reader', 'provenance.json');
const STATE_PATH = path.join(ROOT, '.truth_reader', 'state.json');
const STATUS_PATH = path.join(ROOT, '.truth_reader', 'status.json');

function readJson(file) {
  return JSON.parse(fs.readFileSync(file, 'utf8'));
}

function writeJson(file, data) {
  fs.mkdirSync(path.dirname(file), { recursive: true });
  fs.writeFileSync(file, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

function getSourceProvenance(sourceRelPath) {
  const fullPath = path.join(ROOT, sourceRelPath);
  if (!fs.existsSync(fullPath)) {
    throw new Error(`Canonical source document missing: ${sourceRelPath}`);
  }
  let blobSha = null;
  let commitSha = null;
  try {
    blobSha = execSync(`git rev-parse HEAD:${sourceRelPath}`, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
  } catch (err) {
    const content = fs.readFileSync(fullPath);
    const header = Buffer.from(`blob ${content.length}\0`);
    blobSha = crypto.createHash('sha1').update(Buffer.concat([header, content])).digest('hex');
  }
  try {
    commitSha = execSync(`git log -1 --format=%H -- "${sourceRelPath}"`, { cwd: ROOT, encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] }).trim();
  } catch (err) {
    commitSha = 'uncommitted-or-initial';
  }
  return { blobSha, commitSha };
}

function parseMarkdownToParagraphArray(content) {
  const lines = content.split(/\r?\n/);
  const records = [];
  let currentTopic = null;
  let buffer = [];
  let recordIndex = 0;

  function flushBuffer() {
    if (buffer.length === 0) return;
    const text = buffer.join('\n').trim();
    if (text.length > 0) {
      records.push({
        index: recordIndex++,
        topic: currentTopic,
        text: text
      });
    }
    buffer = [];
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const headerMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headerMatch) {
      flushBuffer();
      currentTopic = headerMatch[2].trim();
      records.push({
        index: recordIndex++,
        topic: currentTopic,
        text: line
      });
      continue;
    }
    if (line.trim() === '') {
      flushBuffer();
    } else {
      buffer.push(line);
    }
  }
  flushBuffer();
  return records;
}

function parseJsonToElementArray(rawJson) {
  const parsed = JSON.parse(rawJson);
  const records = [];
  let recordIndex = 0;

  function traverse(value, jsonPath) {
    if (value !== null && typeof value === 'object') {
      if (Array.isArray(value)) {
        records.push({
          index: recordIndex++,
          path: jsonPath,
          node_type: 'array_open',
          length: value.length
        });
        for (let i = 0; i < value.length; i++) {
          traverse(value[i], `${jsonPath}[${i}]`);
        }
        records.push({
          index: recordIndex++,
          path: jsonPath,
          node_type: 'array_close'
        });
      } else {
        records.push({
          index: recordIndex++,
          path: jsonPath,
          node_type: 'object_open',
          keys: Object.keys(value)
        });
        for (const [k, v] of Object.entries(value)) {
          traverse(v, jsonPath ? `${jsonPath}.${k}` : k);
        }
        records.push({
          index: recordIndex++,
          path: jsonPath,
          node_type: 'object_close'
        });
      }
    } else {
      records.push({
        index: recordIndex++,
        path: jsonPath,
        node_type: 'primitive',
        value: value
      });
    }
  }

  traverse(parsed, '$');
  return records;
}

function generateReaderProjection(docId, docConfig) {
  const fullSourcePath = path.join(ROOT, docConfig.source_path);
  const raw = fs.readFileSync(fullSourcePath, 'utf8');
  let items = [];
  if (docConfig.format === 'json') {
    items = parseJsonToElementArray(raw);
  } else {
    items = parseMarkdownToParagraphArray(raw);
  }

  return {
    doc_id: docId,
    source_path: docConfig.source_path,
    format: docConfig.format,
    total_items: items.length,
    items: items
  };
}

function ensureStableReader(docId, docConfig, provenanceStore) {
  const prov = getSourceProvenance(docConfig.source_path);
  const storedProv = provenanceStore[docId] || {};
  const fullReaderPath = path.join(ROOT, docConfig.stable_reader_path);

  const isMatch =
    fs.existsSync(fullReaderPath) &&
    storedProv.source_blob_sha === prov.blobSha &&
    storedProv.source_commit_sha === prov.commitSha;

  if (isMatch) {
    return readJson(fullReaderPath);
  }

  const projection = generateReaderProjection(docId, docConfig);
  writeJson(fullReaderPath, projection);
  provenanceStore[docId] = {
    source_blob_sha: prov.blobSha,
    source_commit_sha: prov.commitSha,
    updated_at: new Date().toISOString()
  };
  writeJson(PROVENANCE_PATH, provenanceStore);
  return projection;
}

function createActiveSeededProjection(reader, challengeId) {
  const items = JSON.parse(JSON.stringify(reader.items));
  const n = items.length;
  if (n === 0) {
    const seedVal = crypto.randomBytes(16).toString('hex');
    const seedNode = {
      type: 'truth_seed',
      challenge_id: challengeId,
      doc_id: reader.doc_id,
      seed_index: 0,
      seed: seedVal
    };
    return { seededItems: [seedNode], docSeeds: [seedVal] };
  }

  const seedCount = Math.max(3, Math.min(10, Math.floor(n / 4) + 2));
  const targetIndices = [];
  targetIndices.push(0);
  for (let s = 1; s < seedCount - 1; s++) {
    const idx = Math.floor((s * (n - 1)) / (seedCount - 1));
    if (!targetIndices.includes(idx)) targetIndices.push(idx);
  }
  if (!targetIndices.includes(n - 1)) targetIndices.push(n - 1);
  targetIndices.sort((a, b) => a - b);

  const seededItems = [];
  const docSeeds = [];
  let seedSeq = 0;
  let targetPtr = 0;

  for (let i = 0; i < n; i++) {
    if (targetPtr < targetIndices.length && targetIndices[targetPtr] === i) {
      const seedVal = crypto.randomBytes(16).toString('hex');
      docSeeds.push(seedVal);
      seededItems.push({
        type: 'truth_seed',
        challenge_id: challengeId,
        doc_id: reader.doc_id,
        seed_index: seedSeq++,
        seed: seedVal
      });
      targetPtr++;
    }
    seededItems.push(items[i]);
  }

  return { seededItems, docSeeds };
}

function handleGenerate() {
  const catalog = readJson(CATALOG_PATH);
  const selector = readJson(SELECTOR_PATH);
  const provenanceStore = readJson(PROVENANCE_PATH);

  const validKeys = Object.keys(catalog.documents);
  for (const k of Object.keys(selector)) {
    if (!validKeys.includes(k)) {
      throw new Error(`Rejected arbitrary selector path or uncataloged key: ${k}`);
    }
    if (typeof selector[k] !== 'boolean') {
      throw new Error(`Selector values must be strictly boolean: ${k}=${selector[k]}`);
    }
  }

  const selectedDocs = validKeys.filter((k) => selector[k] === true);
  if (selectedDocs.length === 0) {
    process.exit(0);
  }

  const challengeId = `chal_${Date.now()}_${crypto.randomBytes(4).toString('hex')}`;
  const allExpectedSeeds = [];

  for (const docId of selectedDocs) {
    const docConfig = catalog.documents[docId];
    const stableReader = ensureStableReader(docId, docConfig, provenanceStore);
    const { seededItems, docSeeds } = createActiveSeededProjection(stableReader, challengeId);
    allExpectedSeeds.push(...docSeeds);

    const activePayload = {
      challenge_id: challengeId,
      doc_id: docId,
      source_path: docConfig.source_path,
      total_elements: seededItems.length,
      items: seededItems
    };
    writeJson(path.join(ROOT, docConfig.active_projection_path), activePayload);
  }

  const state = {
    active_challenge: true,
    challenge_id: challengeId,
    selected_docs: selectedDocs,
    expected_seeds: allExpectedSeeds,
    created_at: new Date().toISOString()
  };
  writeJson(STATE_PATH, state);

  writeJson(EVIDENCE_PATH, {
    submission_id: null,
    seeds: []
  });
}

function handleVerify() {
  const state = readJson(STATE_PATH);
  if (!state.active_challenge) {
    process.exit(0);
  }

  const evidence = readJson(EVIDENCE_PATH);
  const expected = state.expected_seeds;
  const submitted = Array.isArray(evidence.seeds) ? evidence.seeds : [];

  if (submitted.length === 0) {
    process.exit(1);
  }

  if (submitted.length !== expected.length) {
    process.exit(1);
  }

  for (let i = 0; i < expected.length; i++) {
    if (submitted[i] !== expected[i]) {
      process.exit(1);
    }
  }

  const catalog = readJson(CATALOG_PATH);
  for (const docId of Object.keys(catalog.documents)) {
    const activePath = path.join(ROOT, catalog.documents[docId].active_projection_path);
    if (fs.existsSync(activePath)) {
      fs.unlinkSync(activePath);
    }
  }

  const selector = readJson(SELECTOR_PATH);
  for (const k of Object.keys(selector)) {
    selector[k] = false;
  }
  writeJson(SELECTOR_PATH, selector);

  writeJson(EVIDENCE_PATH, {
    submission_id: null,
    seeds: []
  });

  const audited = state.selected_docs;
  const challengeId = state.challenge_id;
  writeJson(STATE_PATH, {
    active_challenge: false,
    challenge_id: null,
    selected_docs: [],
    expected_seeds: [],
    created_at: null
  });

  writeJson(STATUS_PATH, {
    status: 'PASS',
    last_verified_at: new Date().toISOString(),
    verified_challenge_id: challengeId,
    audited_documents: audited
  });
}

const mode = process.argv[2];
if (mode === 'generate') {
  handleGenerate();
} else if (mode === 'verify') {
  handleVerify();
} else {
  throw new Error(`Usage: node scripts/truth-reader-engine.js [generate|verify]`);
}
